   "wieGefunden": "Nachgerechnet stimmte alles: bei 72 px Abstand und ω = 0,033 ist das Höchsttempo 0,87 px/ms, mal 0,2 macht 1,175. Also musste der Aufruf falsch ankommen, nicht die Formel.",
   "ursache": "`handyLeiste()` läuft je Tipp ZWEIMAL — einmal aus dem Klick, einmal aus dem Ereignis `redion:schauplatz`. Der zweite Ruf traf die laufende Feder; weil `dataset.x` da schon umgeschrieben war, kam er mit „kein Nachbar\" und startete die Bahn neu.",
